# =============================================================================
# tab_district_challenges.R — "District challenges" (School district, 7 of 7)
#
# The district counterpart of "Put it together": a short method for turning a
# data request into a query, fifteen graded requests written the way they
# arrive (from a principal, a coordinator, the cabinet), a free sandbox on the
# district database, ungraded talk-it-through scenarios for interview practice,
# and a note on running SQL against a district's SQL Server from R.
# =============================================================================

DCH_DQUEST <- list(
  list(prompt = paste0("From Oak Grove's principal: “Can I get a list of everyone enrolled here right ",
                       "now?” Oak Grove is school_id 60; now is 2026-03-31; primary enrollments. Return ",
                       "student_id, last_name, first_name, grade, sorted by grade, then last_name, first_name, ",
                       "and student_id."),
       ref = "SELECT s.student_id, s.last_name, s.first_name, e.grade FROM enrollments e JOIN students s ON s.student_id = e.student_id WHERE e.school_id = 60 AND e.service_type = 'P' AND e.start_date <= '2026-03-31' AND (e.end_date IS NULL OR e.end_date >= '2026-03-31') ORDER BY e.grade, s.last_name, s.first_name, s.student_id;",
       ordered = TRUE,
       solution = "SELECT s.student_id, s.last_name, s.first_name, e.grade\nFROM enrollments AS e\nJOIN students AS s ON s.student_id = e.student_id\nWHERE e.school_id = 60\n  AND e.service_type = 'P'\n  AND e.start_date <= '2026-03-31'\n  AND (e.end_date IS NULL OR e.end_date >= '2026-03-31')\nORDER BY e.grade, s.last_name, s.first_name, s.student_id;"),
  list(prompt = paste0("From the cabinet: “Where are we today, school by school?” Return school_name ",
                       "and students (distinct students with a primary enrollment open on 2026-03-31), largest ",
                       "first, ties broken by school_name."),
       ref = "SELECT sc.school_name, COUNT(DISTINCT e.student_id) AS students FROM enrollments e JOIN schools sc ON sc.school_id = e.school_id WHERE e.service_type = 'P' AND e.start_date <= '2026-03-31' AND (e.end_date IS NULL OR e.end_date >= '2026-03-31') GROUP BY sc.school_name ORDER BY students DESC, sc.school_name;",
       ordered = TRUE,
       solution = "SELECT sc.school_name, COUNT(DISTINCT e.student_id) AS students\nFROM enrollments AS e\nJOIN schools AS sc ON sc.school_id = e.school_id\nWHERE e.service_type = 'P'\n  AND e.start_date <= '2026-03-31'\n  AND (e.end_date IS NULL OR e.end_date >= '2026-03-31')\nGROUP BY sc.school_name\nORDER BY students DESC, sc.school_name;"),
  list(prompt = paste0("From the superintendent: “How many students have left the district this year, and ",
                       "why?” For 2026 enrollments whose end code has leaves_district = 1, return the code's ",
                       "description and students (distinct)."),
       ref = "SELECT sc.description, COUNT(DISTINCT e.student_id) AS students FROM enrollments e JOIN status_codes sc ON sc.code = e.end_status AND sc.code_type = 'end' WHERE e.school_year = 2026 AND sc.leaves_district = 1 GROUP BY sc.description;",
       solution = "SELECT sc.description, COUNT(DISTINCT e.student_id) AS students\nFROM enrollments AS e\nJOIN status_codes AS sc\n  ON sc.code = e.end_status\n AND sc.code_type = 'end'\nWHERE e.school_year = 2026\n  AND sc.leaves_district = 1\nGROUP BY sc.description;"),
  list(prompt = paste0("From the EL coordinator: “Which home languages do our current English learners ",
                       "speak?” Students with an EL spell covering 2026-03-31 and a primary enrollment open ",
                       "that day. Return home_language and students."),
       ref = "SELECT st.home_language, COUNT(DISTINCT p.student_id) AS students FROM programs p JOIN students st ON st.student_id = p.student_id JOIN enrollments e ON e.student_id = p.student_id AND e.service_type = 'P' AND e.start_date <= '2026-03-31' AND (e.end_date IS NULL OR e.end_date >= '2026-03-31') WHERE p.program = 'EL' AND p.start_date <= '2026-03-31' AND (p.end_date IS NULL OR p.end_date >= '2026-03-31') GROUP BY st.home_language;",
       solution = "SELECT st.home_language, COUNT(DISTINCT p.student_id) AS students\nFROM programs AS p\nJOIN students AS st ON st.student_id = p.student_id\nJOIN enrollments AS e\n  ON e.student_id = p.student_id\n AND e.service_type = 'P'\n AND e.start_date <= '2026-03-31'\n AND (e.end_date IS NULL OR e.end_date >= '2026-03-31')\nWHERE p.program = 'EL'\n  AND p.start_date <= '2026-03-31'\n  AND (p.end_date IS NULL OR p.end_date >= '2026-03-31')\nGROUP BY st.home_language;"),
  list(prompt = paste0("From Linden Middle School's attendance team: “Who is chronically absent here so ",
                       "far this year?” Using the Attendance tab's three CTEs, return student_id, ",
                       "days_enrolled, days_absent for Linden (school_id 50) records with days_absent / ",
                       "days_enrolled of 0.1 or more."),
       ref = att_sql("SELECT student_id, days_enrolled, days_absent FROM per_student WHERE school_id = 50 AND days_absent * 1.0 / days_enrolled >= 0.1;"),
       solution = att_sql("SELECT student_id, days_enrolled, days_absent\nFROM per_student\nWHERE school_id = 50\n  AND days_absent * 1.0 / days_enrolled >= 0.1;")),
  list(prompt = paste0("From a board member: “How many students have been involved, as an offender, in ",
                       "three or more incidents this year?” This year: incident_date on or after ",
                       "2025-07-01. One column, students."),
       ref = "SELECT COUNT(*) AS students FROM (SELECT p.student_id FROM incident_students p JOIN incidents i ON i.incident_id = p.incident_id WHERE p.role = 'Offender' AND i.incident_date >= '2025-07-01' GROUP BY p.student_id HAVING COUNT(*) >= 3);",
       solution = "SELECT COUNT(*) AS students\nFROM (\n  SELECT p.student_id\n  FROM incident_students AS p\n  JOIN incidents AS i ON i.incident_id = p.incident_id\n  WHERE p.role = 'Offender'\n    AND i.incident_date >= '2025-07-01'\n  GROUP BY p.student_id\n  HAVING COUNT(*) >= 3\n);"),
  list(prompt = paste0("From a Lakeview counselor: “Which of my seniors are below 18 credits?” Students ",
                       "with a primary grade 12 enrollment at Lakeview (school_id 70) open on 2026-03-31; ",
                       "credits = all their transcript credits_earned (transfer and converted credit ",
                       "included). Return student_id and credits."),
       ref = "SELECT e.student_id, SUM(t.credits_earned) AS credits FROM enrollments e LEFT JOIN transcripts t ON t.student_id = e.student_id WHERE e.school_id = 70 AND e.grade = '12' AND e.service_type = 'P' AND e.start_date <= '2026-03-31' AND (e.end_date IS NULL OR e.end_date >= '2026-03-31') GROUP BY e.student_id HAVING SUM(t.credits_earned) < 18 OR SUM(t.credits_earned) IS NULL;",
       solution = "SELECT e.student_id, SUM(t.credits_earned) AS credits\nFROM enrollments AS e\nLEFT JOIN transcripts AS t ON t.student_id = e.student_id\nWHERE e.school_id = 70\n  AND e.grade = '12'\n  AND e.service_type = 'P'\n  AND e.start_date <= '2026-03-31'\n  AND (e.end_date IS NULL OR e.end_date >= '2026-03-31')\nGROUP BY e.student_id\nHAVING SUM(t.credits_earned) < 18\n    OR SUM(t.credits_earned) IS NULL;"),
  list(prompt = paste0("From Riverside's assistant principal, building next year's schedule: “How many ",
                       "second-semester sections does each of our teachers have?” For school_id 80, term ",
                       "'S2', return staff_id, last_name, and sections."),
       ref = "SELECT st.staff_id, st.last_name, COUNT(*) AS sections FROM sections s JOIN staff st ON st.staff_id = s.teacher_id WHERE s.school_id = 80 AND s.term = 'S2' GROUP BY st.staff_id, st.last_name;",
       solution = "SELECT st.staff_id, st.last_name, COUNT(*) AS sections\nFROM sections AS s\nJOIN staff AS st ON st.staff_id = s.teacher_id\nWHERE s.school_id = 80\n  AND s.term = 'S2'\nGROUP BY st.staff_id, st.last_name;"),
  list(prompt = paste0("From the teachers' union, during negotiations: “What is the average class size this ",
                       "semester?” For S2 sections with period > 0 (not advisory), students on the roster ",
                       "on 2026-03-31 divided by the number of sections, by school. Return school_id and ",
                       "avg_class_size rounded to 1. Sections with nobody on the roster still count."),
       ref = "SELECT s.school_id, ROUND(1.0 * COUNT(r.roster_id) / COUNT(DISTINCT s.section_id), 1) AS avg_class_size FROM sections s LEFT JOIN roster r ON r.section_id = s.section_id AND r.start_date <= '2026-03-31' AND r.end_date >= '2026-03-31' WHERE s.term = 'S2' AND s.period > 0 GROUP BY s.school_id;",
       solution = "SELECT s.school_id,\n       ROUND(1.0 * COUNT(r.roster_id) / COUNT(DISTINCT s.section_id), 1) AS avg_class_size\nFROM sections AS s\nLEFT JOIN roster AS r\n       ON r.section_id = s.section_id\n      AND r.start_date <= '2026-03-31'\n      AND r.end_date >= '2026-03-31'\nWHERE s.term = 'S2'\n  AND s.period > 0\nGROUP BY s.school_id;"),
  list(prompt = paste0("From the state reporting coordinator: “Who is enrolled today without a state ",
                       "ID?” Return student_id, last_name, first_name, school_id."),
       ref = "SELECT s.student_id, s.last_name, s.first_name, e.school_id FROM students s JOIN enrollments e ON e.student_id = s.student_id AND e.service_type = 'P' AND e.start_date <= '2026-03-31' AND (e.end_date IS NULL OR e.end_date >= '2026-03-31') WHERE s.state_id IS NULL;",
       solution = "SELECT s.student_id, s.last_name, s.first_name, e.school_id\nFROM students AS s\nJOIN enrollments AS e\n  ON e.student_id = s.student_id\n AND e.service_type = 'P'\n AND e.start_date <= '2026-03-31'\n AND (e.end_date IS NULL OR e.end_date >= '2026-03-31')\nWHERE s.state_id IS NULL;"),
  list(prompt = paste0("From the equity office: “Are students from low-income families taking AP courses at ",
                       "the same rate?” High school students (primary enrollment at school 70, 80, or 90 open ",
                       "on 2025-10-01), grouped by FRL status on that date ('FRL' or 'Not FRL'); AP takers are ",
                       "those with a 2026 S1 transcript row in a course whose course_level is 'AP'. Return frl, ",
                       "students, ap_takers, pct (rounded to 3)."),
       ref = "WITH hs AS (SELECT DISTINCT student_id FROM enrollments WHERE school_id IN (70, 80, 90) AND service_type = 'P' AND start_date <= '2025-10-01' AND (end_date IS NULL OR end_date >= '2025-10-01')), f AS (SELECT DISTINCT student_id FROM programs WHERE program = 'FRL' AND start_date <= '2025-10-01' AND (end_date IS NULL OR end_date >= '2025-10-01')), ap AS (SELECT DISTINCT t.student_id FROM transcripts t JOIN courses c ON c.course_id = t.course_id WHERE t.school_year = 2026 AND t.term = 'S1' AND c.course_level = 'AP') SELECT CASE WHEN f.student_id IS NULL THEN 'Not FRL' ELSE 'FRL' END AS frl, COUNT(*) AS students, SUM(CASE WHEN ap.student_id IS NOT NULL THEN 1 ELSE 0 END) AS ap_takers, ROUND(1.0 * SUM(CASE WHEN ap.student_id IS NOT NULL THEN 1 ELSE 0 END) / COUNT(*), 3) AS pct FROM hs LEFT JOIN f ON f.student_id = hs.student_id LEFT JOIN ap ON ap.student_id = hs.student_id GROUP BY frl;",
       solution = "WITH hs AS (\n  SELECT DISTINCT student_id FROM enrollments\n  WHERE school_id IN (70, 80, 90) AND service_type = 'P'\n    AND start_date <= '2025-10-01'\n    AND (end_date IS NULL OR end_date >= '2025-10-01')\n),\nf AS (\n  SELECT DISTINCT student_id FROM programs\n  WHERE program = 'FRL' AND start_date <= '2025-10-01'\n    AND (end_date IS NULL OR end_date >= '2025-10-01')\n),\nap AS (\n  SELECT DISTINCT t.student_id\n  FROM transcripts AS t\n  JOIN courses AS c ON c.course_id = t.course_id\n  WHERE t.school_year = 2026 AND t.term = 'S1' AND c.course_level = 'AP'\n)\nSELECT CASE WHEN f.student_id IS NULL THEN 'Not FRL' ELSE 'FRL' END AS frl,\n       COUNT(*) AS students,\n       SUM(CASE WHEN ap.student_id IS NOT NULL THEN 1 ELSE 0 END) AS ap_takers,\n       ROUND(1.0 * SUM(CASE WHEN ap.student_id IS NOT NULL THEN 1 ELSE 0 END) / COUNT(*), 3) AS pct\nFROM hs\nLEFT JOIN f  ON f.student_id  = hs.student_id\nLEFT JOIN ap ON ap.student_id = hs.student_id\nGROUP BY frl;"),
  list(prompt = paste0("For a school report card: spring 2025 Mathematics, by school: tested (students with ",
                       "test_status 'Tested') and pct_proficient (Meets or Exceeds among tested, rounded to 3), ",
                       "with pct_proficient NULL when fewer than 10 tested. Return school_id, tested, ",
                       "pct_proficient."),
       ref = "SELECT school_id, SUM(CASE WHEN test_status = 'Tested' THEN 1 ELSE 0 END) AS tested, CASE WHEN SUM(CASE WHEN test_status = 'Tested' THEN 1 ELSE 0 END) < 10 THEN NULL ELSE ROUND(1.0 * SUM(CASE WHEN achievement_level IN ('Meets', 'Exceeds') THEN 1 ELSE 0 END) / SUM(CASE WHEN test_status = 'Tested' THEN 1 ELSE 0 END), 3) END AS pct_proficient FROM test_results WHERE school_year = 2025 AND subject = 'Mathematics' GROUP BY school_id;",
       solution = "SELECT school_id,\n       SUM(CASE WHEN test_status = 'Tested' THEN 1 ELSE 0 END) AS tested,\n       CASE WHEN SUM(CASE WHEN test_status = 'Tested' THEN 1 ELSE 0 END) < 10 THEN NULL\n            ELSE ROUND(1.0 * SUM(CASE WHEN achievement_level IN ('Meets', 'Exceeds') THEN 1 ELSE 0 END)\n                           / SUM(CASE WHEN test_status = 'Tested' THEN 1 ELSE 0 END), 3)\n       END AS pct_proficient\nFROM test_results\nWHERE school_year = 2025\n  AND subject = 'Mathematics'\nGROUP BY school_id;"),
  list(prompt = paste0("For next year's enrollment projection: from the frozen snapshots, each year's grade 01 ",
                       "count divided by the previous year's KG count (how much of a kindergarten class comes ",
                       "back as first graders). Return school_year and ratio rounded to 3, for 2023 to 2026."),
       ref = "WITH k AS (SELECT school_year, SUM(CASE WHEN grade = 'KG' THEN 1 ELSE 0 END) AS kg, SUM(CASE WHEN grade = '01' THEN 1 ELSE 0 END) AS g1 FROM oct1_snapshot GROUP BY school_year), r AS (SELECT school_year, ROUND(1.0 * g1 / LAG(kg) OVER (ORDER BY school_year), 3) AS ratio FROM k) SELECT school_year, ratio FROM r WHERE school_year >= 2023;",
       solution = "WITH counts AS (\n  SELECT school_year,\n         SUM(CASE WHEN grade = 'KG' THEN 1 ELSE 0 END) AS kg,\n         SUM(CASE WHEN grade = '01' THEN 1 ELSE 0 END) AS g1\n  FROM oct1_snapshot\n  GROUP BY school_year\n),\nratios AS (\n  SELECT school_year,\n         ROUND(1.0 * g1 / LAG(kg) OVER (ORDER BY school_year), 3) AS ratio\n  FROM counts\n)\nSELECT school_year, ratio\nFROM ratios\nWHERE school_year >= 2023;"),
  list(prompt = paste0("From a grant application: “What share of students enrolled on October 1 had left ",
                       "their school by today?” Among primary enrollments open on 2025-10-01, the share that ",
                       "have an end_date. One column, mobility, rounded to 3."),
       ref = "SELECT ROUND(AVG(CASE WHEN end_date IS NOT NULL THEN 1.0 ELSE 0 END), 3) AS mobility FROM enrollments WHERE service_type = 'P' AND start_date <= '2025-10-01' AND (end_date IS NULL OR end_date >= '2025-10-01');",
       solution = "SELECT ROUND(AVG(CASE WHEN end_date IS NOT NULL THEN 1.0 ELSE 0 END), 3) AS mobility\nFROM enrollments\nWHERE service_type = 'P'\n  AND start_date <= '2025-10-01'\n  AND (end_date IS NULL OR end_date >= '2025-10-01');"),
  list(prompt = paste0("From the board, for a trend chart: chronic absence by school for each year in ",
                       "attendance_year_summary (share of rows with days_absent / days_membership >= 0.1, rounded ",
                       "to 3). Return school_id, school_year, chronic_absence, ordered by school_id then ",
                       "school_year."),
       ref = "SELECT school_id, school_year, ROUND(AVG(CASE WHEN days_absent * 1.0 / days_membership >= 0.1 THEN 1.0 ELSE 0 END), 3) AS chronic_absence FROM attendance_year_summary GROUP BY school_id, school_year ORDER BY school_id, school_year;",
       ordered = TRUE,
       solution = "SELECT school_id, school_year,\n       ROUND(AVG(CASE WHEN days_absent * 1.0 / days_membership >= 0.1\n                      THEN 1.0 ELSE 0 END), 3) AS chronic_absence\nFROM attendance_year_summary\nGROUP BY school_id, school_year\nORDER BY school_id, school_year;")
)

DCH_SCENARIOS <- function() list(
  list(q = "“A principal says the enrollment number on our dashboard is wrong.”",
       a = tagList("Ask which number and where they got theirs (the date, the screen, the filter). Pull ",
         "the student list behind each number and compare them with ", kbd("EXCEPT"), " in both ",
         "directions. Classify each difference: a different date, secondary or no-show enrollments, ",
         "a student enrolled at two schools, a correction made after the snapshot, a refresh that ",
         "has not run. Fix the data or the definition; tell the principal which it was.")),
  list(q = "“How would you build a weekly report of students with attendance concerns for each school?”",
       a = tagList("A view holding the attendance definition (days enrolled from the calendar, absences ",
         "with the agreed rules); per-student rates as of the run date; a threshold (chronic, or a ",
         "recent run of absences); restricted by an entitlements table so each principal gets their ",
         "school; scheduled weekly, with the as-of date printed on it. Before launch, check the ",
         "numbers against a few students by hand and agree the definition with the attendance team.")),
  list(q = "“We have four requests due Friday. How do you decide what to do first?”",
       a = tagList("Hard deadlines (state reporting, a board meeting) first. Then what affects the most ",
         "students or the largest decision. Check whether an existing report already answers any of ",
         "them. Tell each requester when to expect theirs. Note which requests recur: those are the ",
         "ones to automate next.")),
  list(q = "“You find an error in a number that has already gone to the board.”",
       a = tagList("Confirm the error and its size; tell your supervisor the same day; prepare the ",
         "corrected figure with a plain explanation of what changed and why; let leadership decide ",
         "how to communicate it. Then fix the cause and add a check so it cannot recur. Speed and ",
         "candor matter more than the size of the error.")),
  list(q = "“A department asks for student-level data with names and home addresses.”",
       a = tagList("Ask what the data is for, then provide only the fields that purpose needs. Student ",
         "education records are private under FERPA and Minnesota's Government Data Practices Act; ",
         "staff see them when their work requires it. Deliver through an approved, permissioned ",
         "channel, not an email attachment, and ask the data practices official when the purpose ",
         "or the requester is outside the usual.")),
  list(q = "“Walk us through how you'd compute a graduation rate.”",
       a = tagList("A cohort fixed by the year of first entering 9th grade; transfers in join it; only ",
         "documented transfers out, emigration, and deaths leave it; graduates with a regular diploma ",
         "within four years over the adjusted cohort. Each student's outcome from their last ",
         "enrollment's exit code, through a lookup of which codes count as documented. Say why the ",
         "district's version will differ from the state's: the state can see other districts."))
)

source_district_challenges_server <- function(input, output, session) {
  wire_quest_editors(DCH_DQUEST, "dzdchq", input, output, session, con_fun = district_con_ro)
  sql_editor_server("dzdchsandbox", input, output, session, con_fun = district_con_ro)

  output$dch_tab_ui <- renderUI({
    div(class = "container-fluid", style = "max-width: 1100px; padding-top: 16px;",
      district_header(
        "District challenges", eyebrow = "School district · 7 of 7",
        p(style = "margin-bottom:6px;",
          "Fifteen requests, written the way they arrive: from a principal, a counselor, the ",
          "cabinet, a board member. None says which tables to use, and most leave a decision ",
          "unstated that you would ask about in real life. The prompt below each one makes that ",
          "decision so the answer can be graded."),
        p(style = "margin-bottom:0;",
          "After them: a free sandbox on the district database, six requests to talk through out ",
          "loud (the interview format), and a note on running these queries against SQL Server from R.")),

      h3("Five questions before writing any SQL", style = "margin:18px 0 8px 0;"),
      term_table(head = c("Ask", "Because"), rows = list(
        c("What decision will this inform?", "It decides the level of detail, the format, and what to leave out."),
        c("Which students?", "Schools, grades, programs, primary enrollments only, which year."),
        c("As of when?", "A date, a window, or a frozen snapshot. Write it into the query once."),
        c("Counted how?", "Students, rows, events, or days. Name the unit in the column header."),
        c("Who will see it?", "Student-level data needs a permissioned channel; public tables need suppression."))),
      p(style = "line-height:1.6;",
        "Then, before sending: compare the total with a number you trust, check the grain (",
        kbd("COUNT(*)"), " against ", kbd("COUNT(DISTINCT student_id)"), "), look at a few ",
        "students by hand, and write the definition and the as-of date on the output."),

      district_quest(DCH_DQUEST, "dzdchq", "Fifteen requests",
        "Three are graded on row order (1, 2, and 15); they say how to sort."),

      div(class = "mt-4 p-3",
          style = "background:#fff; border:1px solid #cfe9df; border-radius:10px;",
        h3("Free sandbox: the district database", style = "margin:0 0 6px 0;"),
        p(style = "line-height:1.6;",
          "Read-only, ungraded. The schema is below if you need a column name."),
        dsql_editor("dzdchsandbox", "SELECT name\nFROM sqlite_master\nWHERE type = 'table'\nORDER BY name;", height = "160px"),
        help_details("The district's tables", district_schema_explorer())),

      h3("Talk it through", style = "margin:24px 0 6px 0;"),
      p(style = "line-height:1.6;",
        "Final-round interviews for district data roles usually include requests like these, ",
        "answered aloud. Answer each yourself before opening the outline."),
      tagList(lapply(DCH_SCENARIOS(), function(sc)
        div(class = "p-3 my-2", style = "background:#fff; border:1px solid #e0e6ea; border-radius:10px;",
            div(style = "font-weight:600; line-height:1.5;", sc$q),
            help_details("An outline of a strong answer", sc$a)))),

      h3("Running SQL against a district database from R", style = "margin:24px 0 6px 0;"),
      p(style = "line-height:1.6;",
        "On the job, the database is SQL Server rather than a file, and the connection goes ",
        "through ODBC with your network login. The query is the same SQL; only the connection ",
        "changes. A parameter (", kbd("?"), ") keeps the as-of date out of the query text:"),
      div(class = "p-3 my-2",
          style = "background:#0f2430; color:#e8f0f3; border-radius:8px; font-family:'JetBrains Mono',monospace; font-size:13px; white-space:pre-wrap; line-height:1.5;",
          "library(DBI)\ncon <- dbConnect(odbc::odbc(),\n                 Driver   = \"ODBC Driver 18 for SQL Server\",\n                 Server   = \"reporting-db.district.local\",   # your district's server\n                 Database = \"SIS_Reporting\",\n                 Trusted_Connection = \"Yes\")             # Windows login, no password in code\n\noct1 <- dbGetQuery(con, \"\n  SELECT school_id, COUNT(DISTINCT student_id) AS students\n  FROM enrollments\n  WHERE service_type = 'P'\n    AND start_date <= ?\n    AND (end_date IS NULL OR end_date >= ?)\n  GROUP BY school_id\", params = list(as.Date(\"2025-10-01\"), as.Date(\"2025-10-01\")))\n\ndbDisconnect(con)"),
      p(style = "line-height:1.6; color:#6b7c85; font-size:13px;",
        "Server and database names are placeholders. Student data never goes in a file that leaves ",
        "the district's systems, and credentials never go in code."),

      div(class = "p-3 my-4", style = sprintf("background:%s; border-radius:10px; color:%s;", D_PAL$bg, D_PAL$fg),
          tags$b("That is the district track."), " Each query tab also ends with an ",
          tags$em("In a school district"), " section applying its clause to this database, if you ",
          "want more practice on a particular clause.")
    )
  })
}
